UPDATE quotes SET source = 'Cited in John Foxe, Actes and Monuments (1563)' WHERE figure_id = 7 AND source = 'Response to Thomas More (circa 1531)' AND text = 'I defy the Pope and all his laws. If God spare my life, ere many years I will cause a boy that driveth the plough shall know more of the Scripture than thou doest.';
