UPDATE quotes SET source = 'History of the Reformation in Scotland, interview with Mary Queen of Scots (1563)' WHERE figure_id = 10 AND source = 'Letter to Mary Queen of Scots (1561)' AND text = 'Madam, I am not master of myself, but must obey him who commands me to speak plain, and to flatter no flesh upon the face of the earth.';
