UPDATE quotes SET source = 'Cited in George Smith, The Life of William Carey, Shoemaker and Missionary (1885)' WHERE figure_id = 18 AND source = 'Memoir of William Carey, cited in George Smith''s biography (1885)' AND text = 'When I am gone, say nothing about Dr. Carey — speak about Dr. Carey''s Saviour.';
