UPDATE quotes SET source = 'Cited in Cobbett''s Parliamentary History of England, vol. 29 (1817)' WHERE figure_id = 52 AND source = 'Journal entry (1788)' AND text = 'Never, never will we desist till we have wiped away this scandal from the Christian name, released ourselves from the load of guilt.';
