UPDATE quotes SET source = 'Dr. Livingstone''s Cambridge Lectures, Lecture I, Senate House (December 4, 1857)' WHERE figure_id = 84 AND source = 'Cambridge address, December 4, 1857' AND text = 'I beg to direct your attention to Africa. I know that in a few years I shall be cut off in that country, which is now open. Do not let it be shut again!';
