UPDATE quotes SET source = 'Cited in Hulda Friedrichs, The Life of General Booth (1913)' WHERE figure_id = 86 AND source = 'The Founder Speaks Again by Cyril Barnes (1960, compiled)' AND text = 'Go for souls, and go for the worst.';
