UPDATE quotes SET source = 'Cited in J. Evan Smith, Booth the Beloved (1949)' WHERE figure_id = 86 AND source = 'In Darkest England (1890)' AND text = 'While women weep as they do now, I''ll fight; while little children go hungry as they do now, I''ll fight.';
