INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Sermon on Isaiah 26 (1565)', 'This, I say, is the victory of faith, when to the midst of death, through the light of God’s word, the afflicted see life.', 'faith,hope,resurrection,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'This, I say, is the victory of faith, when to the midst of death, through the light of God’s word, the afflicted see life.');
